Literal.Value:
'{
 "$schema": "https://vega.github.io/schema/vega/v5.json",
 "description": "Insights em texto gerados por medidas DAX (formato TAG|DESTAQUE|TEXTO|TOM). Cada insight tem uma etiqueta, um destaque numerico e um paragrafo com quebra de linha automatica; a cor da barra lateral indica o tom (alerta, positivo, neutro).",
 "padding": 0,
 "config": {
  "view": {
   "stroke": null
  },
  "text": {
   "font": "Din"
  }
 },
 "data": [
  {
   "name": "dataset"
  },
  {
   "name": "ins",
   "source": "dataset",
   "transform": [
    {
     "type": "formula",
     "as": "id",
     "expr": "datum[''Id'']"
    },
    {
     "type": "formula",
     "as": "parts",
     "expr": "split(isValid(datum[''Insight'']) ? datum[''Insight''] : '''', ''|'')"
    },
    {
     "type": "formula",
     "as": "tag",
     "expr": "datum.parts[0]"
    },
    {
     "type": "formula",
     "as": "big",
     "expr": "datum.parts[1]"
    },
    {
     "type": "formula",
     "as": "texto",
     "expr": "datum.parts[2]"
    },
    {
     "type": "formula",
     "as": "tom",
     "expr": "datum.parts[3]"
    },
    {
     "type": "formula",
     "as": "ctx",
     "expr": "datum[''Insight Contexto'']"
    },
    {
     "type": "filter",
     "expr": "isValid(datum.id) && length(datum.parts) >= 4 && length(datum.texto) > 0"
    },
    {
     "type": "formula",
     "as": "toneColor",
     "expr": "datum.tom === ''alerta'' ? cAlert : (datum.tom === ''positivo'' ? cPositive : cAccent)"
    },
    {
     "type": "collect",
     "sort": {
      "field": "id",
      "order": "ascending"
     }
    }
   ]
  },
  {
   "name": "words",
   "source": "ins",
   "transform": [
    {
     "type": "formula",
     "as": "ws",
     "expr": "split(datum.texto, '' '')"
    },
    {
     "type": "flatten",
     "fields": [
      "ws"
     ],
     "as": [
      "w"
     ],
     "index": "wi"
    },
    {
     "type": "formula",
     "as": "wl",
     "expr": "length(datum.w) + 1"
    },
    {
     "type": "window",
     "groupby": [
      "id"
     ],
     "sort": {
      "field": "wi"
     },
     "ops": [
      "sum"
     ],
     "fields": [
      "wl"
     ],
     "as": [
      "cum"
     ],
     "frame": [
      null,
      0
     ]
    },
    {
     "type": "formula",
     "as": "line",
     "expr": "floor((datum.cum - 1) / maxChars)"
    }
   ]
  },
  {
   "name": "linesBase",
   "source": "words",
   "transform": [
    {
     "type": "aggregate",
     "groupby": [
      "id",
      "line"
     ],
     "ops": [
      "values",
      "min"
     ],
     "fields": [
      "w",
      "wi"
     ],
     "as": [
      "items",
      "wmin"
     ]
    },
    {
     "type": "formula",
     "as": "lineText",
     "expr": "join(pluck(datum.items, ''w''), '' '')"
    },
    {
     "type": "collect",
     "sort": {
      "field": [
       "id",
       "line"
      ],
      "order": [
       "ascending",
       "ascending"
      ]
     }
    }
   ]
  },
  {
   "name": "rowsInfo",
   "source": "linesBase",
   "transform": [
    {
     "type": "aggregate",
     "groupby": [
      "id"
     ],
     "ops": [
      "count"
     ],
     "fields": [
      null
     ],
     "as": [
      "nLines"
     ]
    },
    {
     "type": "lookup",
     "from": "ins",
     "key": "id",
     "fields": [
      "id"
     ],
     "values": [
      "tag",
      "big",
      "tom",
      "toneColor",
      "ctx"
     ],
     "as": [
      "tag",
      "big",
      "tom",
      "toneColor",
      "ctx"
     ]
    },
    {
     "type": "formula",
     "as": "rowH",
     "expr": "max(leftH, datum.nLines * lh) + 2 * rowPad"
    },
    {
     "type": "collect",
     "sort": {
      "field": "id",
      "order": "ascending"
     }
    },
    {
     "type": "window",
     "ops": [
      "sum"
     ],
     "fields": [
      "rowH"
     ],
     "as": [
      "cumH"
     ],
     "frame": [
      null,
      0
     ]
    },
    {
     "type": "formula",
     "as": "rowTop",
     "expr": "topY + datum.cumH - datum.rowH"
    },
    {
     "type": "formula",
     "as": "fits",
     "expr": "datum.rowTop + datum.rowH <= height - pad - footerH"
    },
    {
     "type": "formula",
     "as": "first",
     "expr": "datum.rowTop === topY"
    }
   ]
  },
  {
   "name": "lines",
   "source": "linesBase",
   "transform": [
    {
     "type": "lookup",
     "from": "rowsInfo",
     "key": "id",
     "fields": [
      "id"
     ],
     "values": [
      "rowTop",
      "fits"
     ],
     "as": [
      "rowTop",
      "fits"
     ]
    }
   ]
  },
  {
   "name": "hidden",
   "source": "rowsInfo",
   "transform": [
    {
     "type": "filter",
     "expr": "!datum.fits"
    },
    {
     "type": "aggregate",
     "ops": [
      "count"
     ],
     "fields": [
      null
     ],
     "as": [
      "n"
     ]
    }
   ]
  },
  {
   "name": "ctxRow",
   "source": "ins",
   "transform": [
    {
     "type": "aggregate",
     "ops": [
      "max"
     ],
     "fields": [
      "ctx"
     ],
     "as": [
      "ctx"
     ]
    }
   ]
  },
  {
   "name": "emptyState",
   "values": [
    {
     "k": 1
    }
   ],
   "transform": [
    {
     "type": "filter",
     "expr": "length(data(''ins'')) === 0"
    }
   ]
  }
 ],
 "signals": [
  {
   "name": "cText",
   "value": "#F4F6F8"
  },
  {
   "name": "cTextMuted",
   "value": "#AEB6C2"
  },
  {
   "name": "cSurface",
   "value": "#15191F"
  },
  {
   "name": "cSurface2",
   "value": "#1D232B"
  },
  {
   "name": "cBorder",
   "value": "#2A323C"
  },
  {
   "name": "cAccent",
   "value": "#5BC0EB"
  },
  {
   "name": "cPositive",
   "value": "#3DDC97"
  },
  {
   "name": "cAlert",
   "value": "#F5B544"
  },
  {
   "name": "fs",
   "update": "max(0.8, min(1.2, min(width / 760, height / 420)))"
  },
  {
   "name": "pad",
   "update": "max(12, min(22, width * 0.03))"
  },
  {
   "name": "gap",
   "update": "max(10, 14 * fs)"
  },
  {
   "name": "radius",
   "update": "max(10, min(18, height * 0.05))"
  },
  {
   "name": "fsTitle",
   "update": "max(10.5, 11 * fs)"
  },
  {
   "name": "fsTag",
   "update": "max(9.5, 10 * fs)"
  },
  {
   "name": "fsBody",
   "update": "max(11, 12.5 * fs)"
  },
  {
   "name": "lh",
   "update": "fsBody * 1.4"
  },
  {
   "name": "bigMax",
   "update": "max(18, 24 * fs)"
  },
  {
   "name": "rowPad",
   "update": "max(8, 10 * fs)"
  },
  {
   "name": "barW",
   "update": "4"
  },
  {
   "name": "innerW",
   "update": "max(0, width - 2 * pad)"
  },
  {
   "name": "colW",
   "update": "max(100, min(170, innerW * 0.22))"
  },
  {
   "name": "textX",
   "update": "pad + barW + gap + colW + gap"
  },
  {
   "name": "textW",
   "update": "max(60, width - pad - textX)"
  },
  {
   "name": "maxChars",
   "update": "max(12, floor(textW / (fsBody * 0.58) * 0.92))"
  },
  {
   "name": "leftH",
   "update": "fsTag + 6 + bigMax + 2"
  },
  {
   "name": "stackedHeader",
   "update": "width < 640"
  },
  {
   "name": "headerH",
   "update": "fsTitle + 16 + (stackedHeader ? fsTag + 6 : 0)"
  },
  {
   "name": "topY",
   "update": "pad + headerH"
  },
  {
   "name": "footerH",
   "update": "fsTag + 12"
  }
 ],
 "marks": [
  {
   "name": "shadow",
   "type": "rect",
   "encode": {
    "update": {
     "x": {
      "value": 3
     },
     "y": {
      "value": 3
     },
     "width": {
      "signal": "max(0, width - 3)"
     },
     "height": {
      "signal": "max(0, height - 3)"
     },
     "cornerRadius": {
      "signal": "radius"
     },
     "fill": {
      "value": "#000000"
     },
     "fillOpacity": {
      "value": 0.28
     }
    }
   }
  },
  {
   "name": "surface",
   "type": "rect",
   "encode": {
    "update": {
     "x": {
      "value": 0
     },
     "y": {
      "value": 0
     },
     "width": {
      "signal": "max(0, width - 3)"
     },
     "height": {
      "signal": "max(0, height - 3)"
     },
     "cornerRadius": {
      "signal": "radius"
     },
     "fill": {
      "signal": "cSurface"
     },
     "stroke": {
      "signal": "cBorder"
     },
     "strokeWidth": {
      "value": 1
     }
    }
   }
  },
  {
   "name": "title",
   "type": "text",
   "encode": {
    "update": {
     "x": {
      "signal": "pad"
     },
     "y": {
      "signal": "pad"
     },
     "text": {
      "value": "INSIGHTS DO PERÍODO"
     },
     "baseline": {
      "value": "top"
     },
     "fill": {
      "signal": "cTextMuted"
     },
     "fontSize": {
      "signal": "fsTitle"
     },
     "fontWeight": {
      "value": 600
     }
    }
   }
  },
  {
   "name": "context",
   "type": "text",
   "from": {
    "data": "ctxRow"
   },
   "interactive": false,
   "encode": {
    "update": {
     "x": {
      "signal": "stackedHeader ? pad : width - pad"
     },
     "y": {
      "signal": "stackedHeader ? pad + fsTitle + 6 : pad"
     },
     "text": {
      "field": "ctx"
     },
     "align": {
      "signal": "stackedHeader ? ''left'' : ''right''"
     },
     "baseline": {
      "value": "top"
     },
     "fill": {
      "signal": "cTextMuted"
     },
     "fontSize": {
      "signal": "fsTag + 0.5"
     },
     "limit": {
      "signal": "stackedHeader ? innerW : max(0, innerW - 170)"
     }
    }
   }
  },
  {
   "name": "dividers",
   "type": "rule",
   "from": {
    "data": "rowsInfo"
   },
   "interactive": false,
   "encode": {
    "update": {
     "x": {
      "signal": "pad"
     },
     "x2": {
      "signal": "width - pad"
     },
     "y": {
      "signal": "datum.rowTop"
     },
     "stroke": {
      "signal": "cBorder"
     },
     "strokeOpacity": {
      "signal": "datum.first || !datum.fits ? 0 : 0.9"
     }
    }
   }
  },
  {
   "name": "toneBars",
   "type": "rect",
   "from": {
    "data": "rowsInfo"
   },
   "interactive": false,
   "encode": {
    "update": {
     "x": {
      "signal": "pad"
     },
     "width": {
      "signal": "barW"
     },
     "y": {
      "signal": "datum.rowTop + rowPad"
     },
     "height": {
      "signal": "max(4, datum.rowH - 2 * rowPad)"
     },
     "cornerRadius": {
      "value": 2
     },
     "fill": {
      "field": "toneColor"
     },
     "fillOpacity": {
      "signal": "datum.fits ? 1 : 0"
     }
    }
   }
  },
  {
   "name": "tags",
   "type": "text",
   "from": {
    "data": "rowsInfo"
   },
   "interactive": false,
   "encode": {
    "update": {
     "x": {
      "signal": "pad + barW + gap"
     },
     "y": {
      "signal": "datum.rowTop + rowPad"
     },
     "text": {
      "signal": "datum.fits ? datum.tag : ''''"
     },
     "baseline": {
      "value": "top"
     },
     "fill": {
      "field": "toneColor"
     },
     "fontSize": {
      "signal": "fsTag"
     },
     "fontWeight": {
      "value": 700
     },
     "limit": {
      "signal": "colW + gap - 2"
     }
    }
   }
  },
  {
   "name": "bigs",
   "type": "text",
   "from": {
    "data": "rowsInfo"
   },
   "interactive": false,
   "encode": {
    "update": {
     "x": {
      "signal": "pad + barW + gap"
     },
     "y": {
      "signal": "datum.rowTop + rowPad + fsTag + 6"
     },
     "text": {
      "signal": "datum.fits ? datum.big : ''''"
     },
     "baseline": {
      "value": "top"
     },
     "fill": {
      "signal": "cText"
     },
     "fontSize": {
      "signal": "max(14, min(bigMax, colW / (max(1, length(datum.big)) * 0.62)))"
     },
     "fontWeight": {
      "value": 700
     },
     "limit": {
      "signal": "colW"
     }
    }
   }
  },
  {
   "name": "bodyText",
   "type": "text",
   "from": {
    "data": "lines"
   },
   "interactive": false,
   "encode": {
    "update": {
     "x": {
      "signal": "textX"
     },
     "y": {
      "signal": "datum.rowTop + rowPad + datum.line * lh"
     },
     "text": {
      "signal": "datum.fits ? datum.lineText : ''''"
     },
     "baseline": {
      "value": "top"
     },
     "fill": {
      "signal": "cText"
     },
     "fontSize": {
      "signal": "fsBody"
     },
     "limit": {
      "signal": "textW"
     }
    }
   }
  },
  {
   "name": "hiddenNote",
   "type": "text",
   "from": {
    "data": "hidden"
   },
   "interactive": false,
   "encode": {
    "update": {
     "x": {
      "signal": "pad"
     },
     "y": {
      "signal": "height - pad - 2"
     },
     "text": {
      "signal": "''+ '' + datum.n + (datum.n === 1 ? '' insight não cabe'' : '' insights não cabem'') + '' — aumente a altura do visual''"
     },
     "baseline": {
      "value": "bottom"
     },
     "fill": {
      "signal": "cAlert"
     },
     "fontSize": {
      "signal": "fsTag"
     },
     "fontWeight": {
      "value": 600
     }
    }
   }
  },
  {
   "name": "footerNote",
   "type": "text",
   "from": {
    "data": "ctxRow"
   },
   "interactive": false,
   "encode": {
    "update": {
     "x": {
      "signal": "width - pad"
     },
     "y": {
      "signal": "height - pad - 2"
     },
     "text": {
      "signal": "length(data(''hidden'')) > 0 ? '''' : ''Textos gerados a partir dos filtros do relatório''"
     },
     "align": {
      "value": "right"
     },
     "baseline": {
      "value": "bottom"
     },
     "fill": {
      "signal": "cTextMuted"
     },
     "fontSize": {
      "signal": "fsTag"
     },
     "opacity": {
      "value": 0.8
     }
    }
   }
  },
  {
   "name": "emptyMessage",
   "type": "text",
   "from": {
    "data": "emptyState"
   },
   "interactive": false,
   "encode": {
    "update": {
     "x": {
      "signal": "width / 2"
     },
     "y": {
      "signal": "height / 2"
     },
     "text": {
      "value": "Sem dados para o contexto selecionado"
     },
     "align": {
      "value": "center"
     },
     "baseline": {
      "value": "middle"
     },
     "fill": {
      "signal": "cTextMuted"
     },
     "fontSize": {
      "signal": "max(12, 14 * fs)"
     },
     "limit": {
      "signal": "max(0, width - 2 * pad)"
     }
    }
   }
  }
 ]
}'

'{
  "autosize": {
    "contains": "padding",
    "type": "fit"
  },
  "view": {
    "stroke": "transparent"
  },
  "font": "Segoe UI, wf_segoe-ui_normal, helvetica, arial, sans-serif",
  "arc": {},
  "area": {
    "line": true,
    "opacity": 0.6
  },
  "bar": {},
  "line": {
    "strokeWidth": 3,
    "strokeCap": "round",
    "strokeJoin": "round"
  },
  "point": {
    "filled": true,
    "size": 75
  },
  "rect": {},
  "text": {
    "font": "Din, wf_segoe-ui_normal, helvetica, arial, sans-serif",
    "fontSize": 12,
    "fill": "#616161"
  },
  "axis": {
    "ticks": false,
    "grid": false,
    "domain": false,
    "labelColor": "#616161",
